// Build a posture digest from the timeseries (latest point per severity series).
const series = $input.first().json.series || [];
const lines = series.map((s) => {
  const pts = s.points || [];
  const last = pts.length ? pts[pts.length - 1] : { value: 0 };
  const prev = pts.length > 1 ? pts[pts.length - 2] : { value: last.value };
  const delta = Number(last.value) - Number(prev.value);
  const arrow = delta > 0 ? ':small_red_triangle: +' + delta : delta < 0 ? ':small_red_triangle_down: ' + delta : ':heavy_minus_sign: 0';
  return '> ' + s.key + ': ' + last.value + '  (' + arrow + ')';
});
const text = ':bar_chart: *Darkmoon security posture — daily digest*\n' + (lines.join('\n') || '> no data');
return [{ json: { text } }];
